), inserted as (
  insert into public.sales (
    id, store_id, receipt_number, cashier_id, cashier_name, items, total,
    cost_total, payment_method, cash_received, change_due, status,
    correction_reason, business_date, created_at, updated_at,
    payment_breakdown, payment_edit_history
  )
  select
    (sale->>'id')::uuid,
    '24a3a058-991b-4b64-b1d2-912910842d34'::uuid,
    sale->>'receipt',
    null,
    sale->>'cashier',
    sale->'items',
    (sale->>'total')::bigint,
    (sale->>'costTotal')::bigint,
    sale->>'paymentMethod',
    (sale->>'cashReceived')::bigint,
    (sale->>'changeDue')::bigint,
    'completed'::sale_status,
    sale->>'reason',
    (sale->>'date')::date,
    ((sale->>'date')::date::timestamp at time zone 'Asia/Jakarta'),
    ((sale->>'date')::date::timestamp at time zone 'Asia/Jakarta'),
    sale->'paymentBreakdown',
    '[]'::jsonb
  from payload
  where not exists (
    select 1 from public.sales existing
    where existing.id = (sale->>'id')::uuid
  )
  on conflict (id) do nothing
  returning id
)
select count(*) as inserted_sales from inserted;

update public.sales
set receipt_number = 'IMPORT-TMP-' || id::text
where store_id = '24a3a058-991b-4b64-b1d2-912910842d34'::uuid
  and correction_reason = 'Historical Excel import 2026-09-01 to 2026-09-21'
  and business_date between date '2026-09-01' and date '2026-09-30';

with numbered as (
  select id,
         to_char(business_date, 'DDMMYY') || '-' ||
         lpad((row_number() over (
           partition by store_id, date_trunc('month', business_date)
           order by business_date, created_at, id
         ) + (
           select count(*)
           from public.sales existing
           where existing.store_id = '24a3a058-991b-4b64-b1d2-912910842d34'::uuid
             and existing.business_date between date '2026-09-01' and date '2026-09-30'
             and existing.correction_reason is distinct from 'Historical Excel import 2026-09-01 to 2026-09-21'
         ))::text, 4, '0') as receipt_number
  from public.sales
  where store_id = '24a3a058-991b-4b64-b1d2-912910842d34'::uuid
    and correction_reason = 'Historical Excel import 2026-09-01 to 2026-09-21'
    and business_date between date '2026-09-01' and date '2026-09-30'
)
update public.sales sales
set receipt_number = numbered.receipt_number
from numbered
where sales.id = numbered.id;

insert into public.pos_receipt_sequences (store_id, month_key, last_number)
select store_id, '202609', count(*)
from public.sales
where store_id = '24a3a058-991b-4b64-b1d2-912910842d34'::uuid
  and business_date between date '2026-09-01' and date '2026-09-30'
group by store_id
on conflict (store_id, month_key) do update
set last_number = excluded.last_number;

commit;
